<script setup lang="ts">import {computed,ref} from 'vue';import{useI18n}from'vue-i18n';import{runSingleFlightComparison,type SingleFlightRun}from'@concurrency-lab/scenario-engine';const{locale}=useI18n();const id=ref('Moein');const subscribers=ref(3);const cancelOne=ref(true);const swr=ref(true);const comparison=ref<ReturnType<typeof runSingleFlightComparison>|null>(null);const step=ref(0);const fa=computed(()=>locale.value==='fa');const total=computed(()=>comparison.value?Math.max(comparison.value.broken.events.length,comparison.value.fixed.events.length):0);function run(){comparison.value=runSingleFlightComparison({seed:'phase-5',resourceId:id.value,subscribers:subscribers.value,...(cancelOne.value?{cancelSubscriber:2}:{}),staleWhileRefresh:swr.value});step.value=1}function events(l:SingleFlightRun){return l.events.slice(0,step.value)}</script>
<template><section class="comparison-controls"><h2>{{fa?'آزمایش fan-out':'Fan-out experiment'}}</h2><p>{{fa?'کلید پس از trim و lowercase ساخته می‌شود. هر دو مسیر همان subscriberها را دارند؛ فقط registry اصلاح‌شده کارهای هم‌زمان را یکی می‌کند.':'The key is normalized with trim and lowercase. Both lanes have the same subscribers; only the fixed registry coalesces concurrent work.'}}</p><div class="controls comparison-control-grid"><label>{{fa?'شناسهٔ منبع':'Resource ID'}}<input v-model="id" /></label><label>{{fa?'مصرف‌کننده‌ها':'Subscribers'}}<input v-model.number="subscribers" type="number" min="2" max="5" /></label><label><input v-model="cancelOne" type="checkbox"/> {{fa?'لغو subscriber دوم':'Cancel subscriber 2'}}</label><label><input v-model="swr" type="checkbox"/> {{fa?'نمایش مقدار cache هنگام refresh':'Show cached value during refresh'}}</label></div><div class="action-row"><button class="primary-action" @click="run">{{fa?'اجرای مقایسه':'Run comparison'}}</button><button v-if="comparison&&step<total" class="secondary-action" @click="step++">{{fa?'رویداد بعدی':'Reveal next event'}}</button></div></section><section v-if="comparison" class="comparison-results"><p><strong>{{fa?'کلید نرمال‌شده':'Normalized key'}}:</strong> <code>{{comparison.key}}</code></p><div class="comparison-grid"><article v-for="lane in ([comparison.broken,comparison.fixed] as SingleFlightRun[])" :key="lane.variant" class="result-panel" :class="lane.variant==='broken'?'lane-broken':'lane-fixed'"><h3>{{lane.variant==='broken'?(fa?'درخواست مستقل':'Independent requests'):(fa?'single-flight':'Single-flight')}}</h3><dl class="metric-grid"><div><dt>{{fa?'فراخوانی producer':'Producer calls'}}</dt><dd>{{lane.producerCalls}}</dd></div><div><dt>{{fa?'نتیجه‌های تحویل‌شده':'Delivered'}}</dt><dd>{{lane.delivered}}</dd></div></dl><p :class="lane.invariant.passed?'pass-label':'failure-badge'">{{lane.invariant.passed?(fa?'یک producer مشترک':'One shared producer'):(fa?'producer تکراری':'Duplicate producers')}}</p><ol class="timeline" aria-live="polite"><li v-for="e in events(lane)" :key="e.sequence"><span class="sequence">{{e.sequence}}</span><span class="event-time">{{e.timestamp}}ms</span><strong>{{e.label}}</strong><span class="event-kind">{{e.kind}}</span></li></ol></article></div></section></template>
